   386  static INLINE void lr_sync_read(void *const lr_sync, int r, int c, int plane) {
   387  #if CONFIG_MULTITHREAD
   388    AV1LrSync *const loop_res_sync = (AV1LrSync *)lr_sync;
   389    const int nsync = loop_res_sync->sync_range;
   390
   391    if (r && !(c & (nsync - 1))) {
   392      pthread_mutex_t *const mutex = &loop_res_sync->mutex_[plane][r - 1];
   393      pthread_mutex_lock(mutex);
   394
   395      while (c > loop_res_sync->cur_sb_col[plane][r - 1] - nsync) {
   396        pthread_cond_wait(&loop_res_sync->cond_[plane][r - 1], mutex);
   397      }
   398      pthread_mutex_unlock(mutex);
   399    }
   400  #else
   401    (void)lr_sync;
   402    (void)r;
   403    (void)c;
   404    (void)plane;
   405  #endif  // CONFIG_MULTITHREAD
   406  }
