   408  static INLINE void lr_sync_write(void *const lr_sync, int r, int c,
   409                                   const int sb_cols, int plane) {
   410  #if CONFIG_MULTITHREAD
   411    AV1LrSync *const loop_res_sync = (AV1LrSync *)lr_sync;
   412    const int nsync = loop_res_sync->sync_range;
   413    int cur;
   414    // Only signal when there are enough filtered SB for next row to run.
   415    int sig = 1;
   416
   417    if (c < sb_cols - 1) {
   418      cur = c;
   419      if (c % nsync) sig = 0;
   420    } else {
   421      cur = sb_cols + nsync;
   422    }
   423
   424    if (sig) {
   425      pthread_mutex_lock(&loop_res_sync->mutex_[plane][r]);
   426
   427      loop_res_sync->cur_sb_col[plane][r] = cur;
   428
   429      pthread_cond_broadcast(&loop_res_sync->cond_[plane][r]);
   430      pthread_mutex_unlock(&loop_res_sync->mutex_[plane][r]);
   431    }
   432  #else
   433    (void)lr_sync;
   434    (void)r;
   435    (void)c;
   436    (void)sb_cols;
   437    (void)plane;
   438  #endif  // CONFIG_MULTITHREAD
   439  }
